import { constants, mkdirSync, promises as fs } from 'fs';
import os from 'os';
import path from 'path';
import {
  mergePreviewRoutes,
  previewRoutesSchema,
} from '../types/preview-routes';
import type { SessionStore } from './SessionStore';
import { errnoCode } from '../utils/errnoCode';
import type { FileHandle } from 'fs/promises';

type WorkItemPreviewContext = {
  sessionId: string;
  workId: string;
  attempt: number;
};
const MAX_PREVIEW_CONTEXT_BYTES = 128 * 1024;
const PRIVATE_DIRECTORY_MODE = 0o700;

export const workItemPreviewRoutesPath = ({
  sessionId,
  workId,
  attempt,
}: WorkItemPreviewContext): string =>
  path.join(
    os.tmpdir(),
    'rivet-work-briefings',
    'session-' + encodeURIComponent(sessionId),
    'work-' +
      encodeURIComponent(workId) +
      '.' +
      attempt +
      '.preview-routes.json',
  );

export const prepareWorkItemPreviewRoutes = (
  context: WorkItemPreviewContext,
): string => {
  const filePath = workItemPreviewRoutesPath(context);
  mkdirSync(path.dirname(filePath), {
    recursive: true,
    mode: PRIVATE_DIRECTORY_MODE,
  });
  return filePath;
};

export const readWorkItemPreviewRoutes = async (
  context: WorkItemPreviewContext,
): Promise<string[] | undefined> => {
  let file: FileHandle;
  try {
    file = await fs.open(
      workItemPreviewRoutesPath(context),
      constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK,
    );
  } catch (error) {
    if (errnoCode(error) === 'ENOENT') return undefined;
    throw error;
  }
  try {
    const stat = await file.stat();
    if (!stat.isFile() || stat.size > MAX_PREVIEW_CONTEXT_BYTES)
      throw new Error(
        'Edited-page metadata must be a bounded regular JSON file',
      );
    const buffer = Buffer.alloc(MAX_PREVIEW_CONTEXT_BYTES + 1);
    let size = 0;
    while (size < buffer.length) {
      const read = await file.read(buffer, size, buffer.length - size, size);
      if (read.bytesRead === 0) break;
      size += read.bytesRead;
    }
    if (size > MAX_PREVIEW_CONTEXT_BYTES)
      throw new Error('Edited-page metadata exceeds the size limit');
    return previewRoutesSchema.parse(
      JSON.parse(buffer.toString('utf8', 0, size)),
    );
  } finally {
    await file.close();
  }
};

export const recordWorkItemPreviewRoutes = async (
  context: WorkItemPreviewContext & { store: SessionStore; leaseId: string },
): Promise<
  | { status: 'succeeded' }
  | { status: 'failed'; error: { code: string; message: string } }
> => {
  if (
    context.store.getWorkItemStatus(context.sessionId, context.workId) !==
    'running'
  )
    return { status: 'succeeded' };
  context.store.validateReportLease({ ...context, workItemId: context.workId });
  try {
    const routes = await readWorkItemPreviewRoutes(context);
    if (routes) {
      if (
        context.store.getWorkItemStatus(context.sessionId, context.workId) !==
        'running'
      )
        return { status: 'succeeded' };
      context.store.validateReportLease({
        ...context,
        workItemId: context.workId,
      });
      const input = context.store.getVariantWorkItemInput(
        context.sessionId,
        context.workId,
      );
      context.store.assignVariantPreviewRoutes({
        sessionId: context.sessionId,
        workItemIds: [context.workId],
        previewRoutes: mergePreviewRoutes(routes, input?.previewRoutes),
      });
    }
    return { status: 'succeeded' };
  } catch {
    return {
      status: 'failed',
      error: {
        code: 'PREVIEW_ROUTE_CONTEXT_INVALID',
        message:
          'Worker edited-page metadata must be a valid, bounded list of app-relative URLs.',
      },
    };
  }
};
